# region: render
def render(raw):
    out = []
    for tok in raw:
        s = tok.strip()
        if s.lstrip('-').isdigit():
            out.append(int(s))
    return out

# region: fold
def fold(xs, limit=5):
    return [v if v <= limit else limit for v in xs[1:]]

# region: digest
def digest(xs):
    return [v for v in xs if v % 2 == 0]

# region: emit
def emit(xs, limit=5):
    return [v if v <= limit else limit for v in xs]

# region: shape
def shape(xs, cut=3):
    lo = [v for v in xs if v < cut]
    hi = [v for v in xs if v >= cut]
    return {'n': len(xs), 'lo': len(lo), 'hi': len(hi)}

# region: intake
def intake(summary, bar=2):
    out = dict(summary)
    out['grade'] = 'high' if summary.get('n', 0) >= bar else 'low'
    return out

# region: run
def run(raw):
    return intake(shape(emit(digest(fold(render(raw))))))

